  slug, title, type, event_date, event_time, venue, suburb, address, price, ticket_url, host,
  image_url, image_credit, image_source, organiser, organiser_note, doors, ages, parking, traders,
  description, source, verification_json
) VALUES (
  'john-legend-the-muse-tour-2027-02-20', 'John Legend - The Muse Tour', 'Music', '2027-02-20', 'Doors 18:00, show 20:00',
  'SunBet Arena, Time Square', 'Waterkloof Glen', '209 Aramist Ave, Waterkloof Glen, Pretoria',
  'Price TBC', 'https://concerts50.com/show/john-legend-in-pretoria-tickets-feb-20-2027', 'Sold via Ticketmaster',
  NULL, NULL, NULL,
  'Big Concerts', NULL, '18:00', NULL, 'On-site parking available', NULL,
  'John Legend brings The Muse Tour to Pretoria on Saturday, 20 February 2027, with a show at the SunBet Arena at Time Square in Waterkloof Glen. The stop follows the release of his latest album, Muse, released on 23 October and co-written and produced with Pharrell Williams in their first joint project together in more than two decades.

The Grammy-winning singer is expected to draw from the new record alongside long-time favourites such as ''All of Me'', ''Ordinary People'' and ''Tonight (Best You Ever Had)''. Pretoria is the only Gauteng date on this South African run, which also stops at the Durban ICC on 23 February and the Grand Arena at GrandWest in Cape Town on 25 February. Doors open at 18:00 ahead of a 20:00 start, with tickets sold through Ticketmaster and Big Concerts, whose general sale opened on 13 November 2026.',
  'agent',
  '["https://www.ewn.co.za/im-coming-back-to-see-you-john-legend-brings-the-muse-tour-to-sa-in-feb-2027/", "https://www.timeout.com/pretoria/music/john-legend-announces-pretoria-stop-on-the-muse-tour", "https://briefly.co.za/entertainment/celebrities/258454-john-legend-brings-muse-tour-sa-february-2027-ticket-details-revealed/"]'
);
